class_name LeatherKit
extends RefCounted
## Wave 66 (concept G look): warm stitched leather + dark wood + brass, one amber accent. Every look
## helper returns a StyleBox: a StyleBoxTexture 9-slice when the art kit has landed (res://assets/ui/bench/
## <name>.png, margins from slices.json next to it) and a StyleBoxFlat fallback otherwise, so a screen
## never depends on the art: drop the PNGs in and the same calls pick them up (no code change).
## `textures = false` forces the flat fallback (tests, perf).
##
##   LeatherKit.panel("main"|"inner"|"header")      big frames
##   LeatherKit.pocket("normal"|"hover"|"selected"|"disabled"|"lit")
##   LeatherKit.button("primary"|"second", "normal"|"pressed"|"disabled"|"hover")
##   LeatherKit.bar(ci, rect, frac, color, tick)    progress bar (never a percentage)
##   LeatherKit.slider(ci, rect, frac)              slider track + knob

const ART_DIR := "res://assets/ui/bench/"
const SLICES := ART_DIR + "slices.json"

const LEATHER := Color(0.20, 0.13, 0.085, 0.96)
const LEATHER_IN := Color(0.14, 0.09, 0.06, 0.96)
const POCKET := Color(0.29, 0.19, 0.12, 1.0)
const POCKET_HOT := Color(0.38, 0.25, 0.15, 1.0)
const POCKET_OFF := Color(0.16, 0.12, 0.09, 1.0)
const WOOD := Color(0.43, 0.28, 0.16, 1.0)
const WOOD_DARK := Color(0.25, 0.16, 0.09, 1.0)
const BRASS := Color(0.78, 0.6, 0.27, 1.0)
const STITCH := Color(0.86, 0.7, 0.45, 0.35)
const AMBER := Color(1.0, 0.78, 0.30)
const AMBER_DEEP := Color(0.93, 0.56, 0.12)
const CREAM := Color(0.97, 0.92, 0.80)
const CREAM_DIM := Color(0.80, 0.72, 0.58)

static var textures := true
static var _cache := {}
static var _slices: Dictionary = {}
static var _slices_read := false

# default 9-slice margins per element (P7 overwrites them in slices.json)
const MARGIN := {"panel_main": 56, "panel_inner": 28, "header_plate": 40, "pocket_normal": 24, "pocket_hover": 24,
	"pocket_selected": 24, "pocket_disabled": 24, "belt_cell": 18, "bar_frame": 12, "btn_primary_n": 28,
	"btn_primary_p": 28, "btn_primary_d": 28, "btn_second_n": 22, "btn_second_p": 22, "slider_track": 10,
	"tab_normal": 22, "tab_active": 22, "scrollbar": 6}


## True when the art of `name` is in the project (and textures are on).
static func has_art(name: String) -> bool:
	return textures and ResourceLoader.exists(ART_DIR + name + ".png")


## The texture of `name`, null when the art has not landed.
static func tex(name: String) -> Texture2D:
	if not has_art(name):
		return null
	if not _cache.has(name):
		_cache[name] = load(ART_DIR + name + ".png")
	return _cache[name]


static func _margin(name: String) -> int:
	if not _slices_read:
		_slices_read = true
		if FileAccess.file_exists(SLICES):
			var j: Variant = JSON.parse_string(FileAccess.get_file_as_string(SLICES))
			if j is Dictionary:
				_slices = j
	var m: Variant = _slices.get(name, MARGIN.get(name, 24))
	return int(m)


# a texture box when the art is there, else null
static func _art(name: String) -> StyleBoxTexture:
	var t := tex(name)
	if t == null:
		return null
	var sb := StyleBoxTexture.new()
	sb.texture = t
	sb.set_texture_margin_all(float(_margin(name)))
	sb.axis_stretch_horizontal = StyleBoxTexture.AXIS_STRETCH_MODE_TILE_FIT
	sb.axis_stretch_vertical = StyleBoxTexture.AXIS_STRETCH_MODE_TILE_FIT
	return sb


static func _flat(bg: Color, radius: int, border: Color, bw: int) -> StyleBoxFlat:
	return UiKit.box(bg, radius, border, bw)


## A big frame: "main" (a column: wood border, leather inside), "inner" (a card in a column), "header" (title plate).
static func panel(kind := "main") -> StyleBox:
	var art := _art("panel_" + kind if kind != "header" else "header_plate")
	if art:
		return art
	match kind:
		"inner":
			return _flat(LEATHER_IN, 8, Color(WOOD_DARK, 0.9), 2)
		"header":
			return _flat(Color(WOOD, 0.95), 8, Color(BRASS, 0.8), 2)
	return _flat(LEATHER, 12, WOOD, 4)


## A pocket / cell: state "normal" | "hover" | "selected" | "disabled" | "lit" (the ghost of an item in a hand).
static func pocket(state := "normal") -> StyleBox:
	var key​ := "pocket_" + (state if state in ["hover", "selected", "disabled"] else "normal")
	var art := _art(key​)
	if art:
		if state == "lit":
			art.modulate_color = Color(1.25, 1.1, 0.85)
		return art
	match state:
		"hover":
			return _flat(POCKET_HOT, 7, Color(AMBER, 0.7), 2)
		"selected":
			return _flat(POCKET_HOT, 7, AMBER, 2)
		"disabled":
			return _flat(POCKET_OFF, 7, Color(WOOD_DARK, 0.6), 1)
		"lit":
			return _flat(Color(0.34, 0.24, 0.12, 1.0), 7, Color(AMBER, 0.5), 1)
	return _flat(POCKET, 7, Color(WOOD_DARK, 0.9), 1)


## A button plate. kind "primary" (the one amber thing on a screen) | "second"; state "normal" | "hover" | "pressed" | "disabled".
static func button(kind := "second", state := "normal") -> StyleBox:
